import{_ as a,o as n,a as p,b as e}from"./app.UgfkfLuP.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"Tensor API","link":"/api/SIMD-API/tensor_api/tensor_api"},{"text":"reg矢量计算","link":"/api/SIMD-API/tensor_api/reg_vector_compute/reg_vector_compute"},{"text":"索引生成","link":"/api/SIMD-API/tensor_api/reg_vector_compute/reg_index/reg_index"},{"text":"iota","link":"/api/SIMD-API/tensor_api/reg_vector_compute/reg_index/iota"}]},"headers":[],"relativePath":"api/SIMD-API/tensor_api/reg_vector_compute/reg_index/iota.md","filePath":"api/SIMD-API/tensor_api/reg_vector_compute/reg_index/iota.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"数据类型","slug":"数据类型","link":"#数据类型"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1793005388000}'),t={name:"api/SIMD-API/tensor_api/reg_vector_compute/reg_index/iota.md"};function l(c,s,o,r,d,i){return n(),p("div",null,[...s[0]||(s[0]=[e(`<div><article class="markdown-body"><h1>iota</h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR&amp;950DT系列产品：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3系列产品：不支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2系列产品：不支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;tensor_api/experimental/arch/vector/reg_index_compute.h&quot;</code>，命名空间为<code>asc::te::experimental</code>。</p><p>以标量<code>start</code>为基值，生成步长为1的递增或递减序列，保存在返回的<a href="../reg_tensor/reg_tensor.html">reg_tensor</a>中。设<code>VL_T</code>为一个矢量数据寄存器可容纳的结果元素个数，序列如下：</p><table><thead><tr><th>order</th><th>结果序列</th></tr></thead><tbody><tr><td>iota_order::increase</td><td><code>{start, start + 1, ..., start + VL_T - 1}</code></td></tr><tr><td>iota_order::decrease</td><td><code>{start + VL_T - 1, start + VL_T - 2, ..., start}</code></td></tr></tbody></table><p>递减模式将递增模式的整个序列反向排列，不是从<code>start</code>逐次减1。例如，int16_t的<code>VL_T</code>为128，<code>start</code>为10时，递增序列为<code>{10, 11, ..., 137}</code>，递减序列为<code>{137, 136, ..., 10}</code>。</p><p>本接口仅在AIV上生效。递增模式调用<code>asc_arange</code>，递减模式调用<code>asc_arange_descend</code>，底层语义请参见<a href="../../../c_api/reg_compute/reg_index/asc_arange.html">asc_arange</a>。</p><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="n">iota_order</span><span class="w"> </span><span class="n">order</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">iota_order</span><span class="o">::</span><span class="n">increase</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="o">&gt;</span>
<span class="n">__simd_callee__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="n">reg_tensor</span><span class="o">&lt;</span><span class="n">Std</span><span class="o">::</span><span class="n">remove_cvref_t</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&gt;</span><span class="w"> </span><span class="n">iota</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">T</span><span class="o">&amp;</span><span class="w"> </span><span class="n">start</span><span class="p">);</span>
</code></pre></div><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 模板参数说明</p><table><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>order</td><td>序列方向。<code>iota_order::increase</code>表示递增，<code>iota_order::decrease</code>表示递减。默认值为<code>iota_order::increase</code>。</td></tr><tr><td>T</td><td>标量start的类型，可由函数实参推导。去除const、volatile和引用限定后须为<a href="#%E6%95%B0%E6%8D%AE%E7%B1%BB%E5%9E%8B">数据类型</a>中支持的类型。</td></tr></tbody></table><p><strong>表2</strong> 函数参数说明</p><table><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>start</td><td>输入</td><td>生成序列的标量基值。递增模式的首元素和递减模式的末元素为start，取值须在对应数据类型的可表示范围内。</td></tr></tbody></table><h2 id="数据类型">数据类型<a class="header-anchor" href="#数据类型">​</a></h2><p>去除const、volatile和引用限定后的T支持：int8_t、int16_t、half、int32_t、float。</p><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>返回<code>reg_tensor&lt;Std::remove_cvref_t&lt;T&gt;&gt;</code>，<code>reg</code>保存生成的序列。当前实现不初始化返回对象的<code>mask</code>。</p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><ul><li><code>order</code>仅支持<code>iota_order::increase</code>和<code>iota_order::decrease</code>。</li><li>生成序列的长度由结果元素类型和寄存器位宽决定，不由<code>start</code>的数值决定。</li><li>整型结果超出对应数据类型的可表示范围时回绕，不触发异常。</li><li>后续操作使用返回对象的掩码前，须通过<a href="../reg_tensor/reg_tensor.html#with_mask">with_mask</a>绑定有效掩码。</li></ul><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><p>以下代码片段在VF中调用。分别生成以10为基值的int32_t递增和递减序列，并通过<a href="../mask_reg_compute/all_mask.html">all_mask</a>为两个结果绑定全有效掩码。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__simd_callee__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">iota_example</span><span class="p">(</span>
<span class="w">    </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">reg_tensor</span><span class="o">&lt;</span><span class="kt">int32_t</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">ascending</span><span class="p">,</span>
<span class="w">    </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">reg_tensor</span><span class="o">&lt;</span><span class="kt">int32_t</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">descending</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="k">const</span><span class="w"> </span><span class="kt">int32_t</span><span class="w"> </span><span class="n">start</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">10</span><span class="p">;</span>
<span class="w">    </span><span class="n">ascending</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">iota</span><span class="p">(</span><span class="n">start</span><span class="p">);</span>
<span class="w">    </span><span class="n">descending</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">iota</span><span class="o">&lt;</span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">iota_order</span><span class="o">::</span><span class="n">decrease</span><span class="o">&gt;</span><span class="p">(</span><span class="n">start</span><span class="p">);</span>
<span class="w">    </span><span class="k">const</span><span class="w"> </span><span class="k">auto</span><span class="w"> </span><span class="n">mask</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">all_mask</span><span class="o">&lt;</span><span class="kt">int32_t</span><span class="o">&gt;</span><span class="p">();</span>
<span class="w">    </span><span class="n">ascending</span><span class="p">.</span><span class="n">with_mask</span><span class="p">(</span><span class="n">mask</span><span class="p">);</span>
<span class="w">    </span><span class="n">descending</span><span class="p">.</span><span class="n">with_mask</span><span class="p">(</span><span class="n">mask</span><span class="p">);</span>
<span class="p">}</span>
</code></pre></div></article></div>`,1)])])}const g=a(t,[["render",l]]);export{h as __pageData,g as default};
